public class ResourcePrefixDetector extends Detector
        implements XmlScanner, ResourceFolderScanner {
    private static final String TAG_RESOURCES = "resources";
    private static final String ATTR_NAME = "name"; // or from SdkConstants

    public static final Issue ISSUE = Issue.create(
            "ResourceName",
            "Resource with Wrong Prefix",
            "...",
            Category.CORRECTNESS,
            6,
            Severity.WARNING,
            new Implementation(ResourcePrefixDetector.class,
                    Scope.RESOURCE_FILE_SCOPE));

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList(TAG_RESOURCES);
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        String prefix = getResourcePrefix(context);
        if (prefix == null || prefix.isEmpty()) return;
        NodeList children = element.getChildNodes();
        for (int i=0; i<children.getLength(); i++) {
            Node child = children.item(i);
            if (child.getNodeType() == Node.ELEMENT_NODE) {
                Element childElement = (Element) child;
                Attr nameAttr = childElement.getAttributeNode(ATTR_NAME);
                if (nameAttr != null) {
                    String name = nameAttr.getValue();
                    if (!name.startsWith(prefix)) {
                        context.report(ISSUE, nameAttr, context.getLocation(nameAttr),
                                String.format("Resource named '%1$s' does not start with the expected prefix '%2$s'", name, prefix));
                    }
                }
            }
        }
    }

    @Override
    public boolean appliesTo(ResourceFolderType folderType) { return true; }

    @Override
    public void checkFolder(ResourceContext context, String folderName) {
        ResourceFolderType folderType = ResourceFolderType.getFolderType(folderName);
        if (folderType == ResourceFolderType.VALUES) return;
        String prefix = getResourcePrefix(context);
        if (prefix == null || prefix.isEmpty()) return;
        File folder = context.getFile();
        File[] files = folder.listFiles();
        if (files == null) return;
        for (File file : files) {
            if (file.isFile() && !file.isHidden()) {
                String baseName = getBaseName(file.getName());
                if (!baseName.startsWith(prefix)) {
                    context.report(ISSUE, Location.create(file),
                            String.format("Resource named '%1$s' does not start with the expected prefix '%2$s'", baseName, prefix));
                }
            }
        }
    }

    private static String getResourcePrefix(Context context) {
        Project project = context.getProject();
        if (project == null) return null;
        LintModelModule module = project.getBuildModule();
        if (module == null) return null;
        return module.getResourcePrefix();
    }

    private static String getBaseName(String fileName) { ... }
}
